SELECT

FROM SYS_COLUMN_DETAIL
WHERE
LOGIC_DEL = 0

    AND USER_ID = #{dto.userId}


    AND HEADER_ID = #{dto.headerId}


    AND TITLE = #{dto.title}


    AND NAME = #{dto.name}


    AND ENABLED = #{dto.enabled}


    AND FIXED = #{dto.fixed}


    AND ELLIPSIS_TOOLTIP = #{dto.ellipsisTooltip}


    AND WIDTH = #{dto.width}


    AND MIN_WIDTH = #{dto.minWidth}


    AND MAX_WIDTH = #{dto.maxWidth}


    AND ORDER_NUM = #{dto.orderNum}


    AND SORTED = #{dto.sorted}


    AND RESIZE_FLAG = #{dto.resizeFlag}

ORDER BY create_time DESC

